"""Schema Registry — structured output contracts for specialist agents.

Each agent (intent, execution, verify) has a default schema that defines
the shape of its output.  Artists can override schemas by placing custom
YAML files in the ``custom/`` subdirectory under each agent folder.

Resolution order for ``load_schema(agent, schema_name)``:

1. ``{agent}/custom/{schema_name}.yaml``
2. ``{agent}/{schema_name}.yaml``
3. ``{agent}/default.yaml``

Schemas support single-level inheritance via an ``extends`` key in the
YAML root.  The base schema fields are merged with the extension, and
the extension wins on conflicts.

Thread-safe caching mirrors the pattern in ``profiles/loader.py``.
"""

from __future__ import annotations

import copy
import threading
from pathlib import Path
from typing import Any

import yaml

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

SCHEMAS_DIR: Path = Path(__file__).parent
"""Directory where agent schema subdirectories live."""

# ---------------------------------------------------------------------------
# Thread-safe cache
# ---------------------------------------------------------------------------

_cache: dict[str, dict[str, Any]] = {}
_cache_lock: threading.Lock = threading.Lock()

# ---------------------------------------------------------------------------
# Internal helpers
# ---------------------------------------------------------------------------


def _load_yaml(path: Path) -> dict[str, Any]:
    """Read and parse a YAML file with explicit UTF-8 encoding."""
    with open(path, encoding="utf-8") as fh:
        data = yaml.safe_load(fh)
    if not isinstance(data, dict):
        raise ValueError(f"Schema at {path} did not parse to a dict")
    return data


def _resolve_schema(agent: str, schema_name: str) -> dict[str, Any]:
    """Find and load a schema file using the resolution chain.

    Resolution order:
    1. ``{agent}/custom/{schema_name}.yaml``
    2. ``{agent}/{schema_name}.yaml``
    3. ``{agent}/default.yaml``

    Raises ``FileNotFoundError`` if no schema can be resolved.
    """
    agent_dir = SCHEMAS_DIR / agent

    # 1. Custom override
    custom_path = agent_dir / "custom" / f"{schema_name}.yaml"
    if custom_path.is_file():
        return _load_yaml(custom_path)

    # 2. Standard name
    standard_path = agent_dir / f"{schema_name}.yaml"
    if standard_path.is_file():
        return _load_yaml(standard_path)

    # 3. Default fallback (only if we weren't already looking for default)
    if schema_name != "default":
        default_path = agent_dir / "default.yaml"
        if default_path.is_file():
            return _load_yaml(default_path)

    raise FileNotFoundError(
        f"No schema found for agent={agent!r}, schema_name={schema_name!r}. "
        f"Searched: {custom_path}, {standard_path}"
    )


def _merge_schemas(
    base: dict[str, Any], extension: dict[str, Any]
) -> dict[str, Any]:
    """Merge *extension* onto *base* (single-level inheritance).

    - ``schema`` metadata is shallow-merged (extension wins).
    - ``fields`` are merged key-by-key; extension fields override base
      fields with the same name.
    - Any other top-level keys from the extension are added.
    """
    merged: dict[str, Any] = copy.deepcopy(base)

    # Merge schema metadata
    if "schema" in extension:
        merged.setdefault("schema", {})
        merged["schema"].update(extension["schema"])

    # Merge fields
    if "fields" in extension:
        merged.setdefault("fields", {})
        merged["fields"].update(copy.deepcopy(extension["fields"]))

    # Copy any other top-level keys from extension
    for key in extension:
        if key not in ("schema", "fields", "extends"):
            merged[key] = copy.deepcopy(extension[key])

    return merged


def _validate_type(
    name: str, value: Any, field_def: dict[str, Any]
) -> list[str]:
    """Validate a single value against its field definition.

    Returns a list of error strings (empty means valid).
    """
    errors: list[str] = []
    field_type = field_def.get("type", "any")

    if field_type == "any":
        return errors

    # --- Scalar types ---
    type_map: dict[str, type | tuple[type, ...]] = {
        "string": str,
        "integer": int,
        "float": (int, float),
        "boolean": bool,
    }

    if field_type in type_map:
        expected = type_map[field_type]
        # bool is subclass of int in Python, exclude it for int/float
        if field_type in ("integer", "float") and isinstance(value, bool):
            errors.append(
                f"Field {name!r}: expected {field_type}, got bool"
            )
        elif not isinstance(value, expected):
            errors.append(
                f"Field {name!r}: expected {field_type}, "
                f"got {type(value).__name__}"
            )

    # --- Range check for float/integer ---
    if field_type in ("float", "integer") and "range" in field_def:
        lo, hi = field_def["range"]
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            if value < lo or value > hi:
                errors.append(
                    f"Field {name!r}: value {value} outside "
                    f"range [{lo}, {hi}]"
                )

    # --- Enum ---
    if field_type == "enum":
        allowed = field_def.get("values", [])
        if value not in allowed:
            errors.append(
                f"Field {name!r}: value {value!r} not in "
                f"allowed values {allowed}"
            )

    # --- list (generic) ---
    if field_type == "list":
        if not isinstance(value, list):
            errors.append(
                f"Field {name!r}: expected list, "
                f"got {type(value).__name__}"
            )
        elif "item_schema" in field_def:
            item_schema = field_def["item_schema"]
            for i, item in enumerate(value):
                if isinstance(item, dict):
                    for sub_name, sub_def in item_schema.items():
                        if isinstance(sub_def, dict):
                            sub_required = sub_def.get("required", True)
                            if sub_name not in item:
                                if sub_required:
                                    errors.append(
                                        f"Field {name!r}[{i}]: "
                                        f"missing required sub-field "
                                        f"{sub_name!r}"
                                    )
                            else:
                                errors.extend(
                                    _validate_type(
                                        f"{name}[{i}].{sub_name}",
                                        item[sub_name],
                                        sub_def,
                                    )
                                )

    # --- list[string] ---
    if field_type == "list[string]":
        if not isinstance(value, list):
            errors.append(
                f"Field {name!r}: expected list[string], "
                f"got {type(value).__name__}"
            )
        else:
            for i, item in enumerate(value):
                if not isinstance(item, str):
                    errors.append(
                        f"Field {name!r}[{i}]: expected string, "
                        f"got {type(item).__name__}"
                    )

    # --- list[integer] ---
    if field_type == "list[integer]":
        if not isinstance(value, list):
            errors.append(
                f"Field {name!r}: expected list[integer], "
                f"got {type(value).__name__}"
            )
        else:
            for i, item in enumerate(value):
                if not isinstance(item, int) or isinstance(item, bool):
                    errors.append(
                        f"Field {name!r}[{i}]: expected integer, "
                        f"got {type(item).__name__}"
                    )

    # --- object ---
    if field_type == "object":
        if not isinstance(value, dict):
            errors.append(
                f"Field {name!r}: expected object, "
                f"got {type(value).__name__}"
            )

    return errors


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------


def load_schema(
    agent: str, schema_name: str = "default"
) -> dict[str, Any]:
    """Load (and cache) an agent output schema.

    Resolution order:
    1. ``{agent}/custom/{schema_name}.yaml``
    2. ``{agent}/{schema_name}.yaml``
    3. ``{agent}/default.yaml``

    If the schema declares ``extends: "other_name"``, the base schema is
    loaded and merged first.

    The returned dict is a deep copy so callers can mutate freely.
    """
    cache_key = f"{agent}:{schema_name}"

    with _cache_lock:
        if cache_key in _cache:
            return copy.deepcopy(_cache[cache_key])

    # --- Resolve outside the lock (I/O) --------------------------------
    schema = _resolve_schema(agent, schema_name)

    # --- Handle inheritance ---
    if "extends" in schema:
        base_name = schema["extends"]
        base = _resolve_schema(agent, base_name)
        schema = _merge_schemas(base, schema)

    # --- Store and return ------------------------------------------------
    with _cache_lock:
        _cache[cache_key] = schema

    return copy.deepcopy(schema)


def validate_output(
    output: dict[str, Any],
    agent: str,
    schema_name: str = "default",
) -> list[str]:
    """Validate an agent output dict against its schema.

    Returns a list of error strings.  An empty list means the output is
    valid.
    """
    schema = load_schema(agent, schema_name)
    fields = schema.get("fields", {})
    errors: list[str] = []

    for field_name, field_def in fields.items():
        if not isinstance(field_def, dict):
            continue

        required = field_def.get("required", False)

        if field_name not in output:
            if required:
                errors.append(
                    f"Missing required field: {field_name!r}"
                )
            continue

        errors.extend(
            _validate_type(field_name, output[field_name], field_def)
        )

    return errors


def list_schemas(agent: str) -> list[str]:
    """List all available schema names for an agent.

    Returns a deterministically sorted list of schema names (without
    the ``.yaml`` extension).
    """
    agent_dir = SCHEMAS_DIR / agent
    names: set[str] = set()

    # Standard schemas
    if agent_dir.is_dir():
        for path in agent_dir.glob("*.yaml"):
            names.add(path.stem)

    # Custom schemas
    custom_dir = agent_dir / "custom"
    if custom_dir.is_dir():
        for path in custom_dir.glob("*.yaml"):
            names.add(path.stem)

    return sorted(names)


def clear_cache() -> None:
    """Drop all cached schemas.  Intended for testing."""
    with _cache_lock:
        _cache.clear()

"""Schema Generator — infer output schemas from example dicts.

Given a concrete example of agent output, the generator produces a YAML
schema definition that can be used with ``loader.validate_output()``.
This lets artists create custom schemas by providing example outputs
rather than hand-writing YAML.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import yaml


# ---------------------------------------------------------------------------
# Data structures
# ---------------------------------------------------------------------------


@dataclass
class InferredField:
    """A single field inferred from an example value."""

    name: str
    type: str
    required: bool = True
    description: str = ""
    example_value: Any = None
    nested_fields: list[InferredField] = field(default_factory=list)


# ---------------------------------------------------------------------------
# Internal helpers
# ---------------------------------------------------------------------------


def _infer_field(name: str, value: Any) -> InferredField:
    """Infer a field definition from a name-value pair.

    Type inference rules:
    - ``str`` -> ``"string"``
    - ``bool`` -> ``"boolean"`` (checked before int since bool is int subclass)
    - ``int`` -> ``"integer"``
    - ``float`` -> ``"float"`` (with auto range [0.0, 1.0] if value is in that range)
    - ``list`` -> ``"list[string]"`` if all str, ``"list"`` with item_schema if
      all dicts, ``"list"`` otherwise
    - ``dict`` -> ``"object"`` with nested fields
    - ``None`` / other -> ``"any"``
    """
    if isinstance(value, str):
        return InferredField(name=name, type="string", example_value=value)

    if isinstance(value, bool):
        return InferredField(name=name, type="boolean", example_value=value)

    if isinstance(value, int):
        return InferredField(name=name, type="integer", example_value=value)

    if isinstance(value, float):
        f = InferredField(name=name, type="float", example_value=value)
        # Auto-detect [0, 1] range for floats in that range
        if 0.0 <= value <= 1.0:
            f.description = "Auto-detected range [0.0, 1.0]"
        return f

    if isinstance(value, list):
        if not value:
            return InferredField(name=name, type="list", example_value=[])

        # Check if all strings
        if all(isinstance(v, str) for v in value):
            return InferredField(
                name=name, type="list[string]", example_value=value
            )

        # Check if all ints (not bools)
        if all(
            isinstance(v, int) and not isinstance(v, bool) for v in value
        ):
            return InferredField(
                name=name, type="list[integer]", example_value=value
            )

        # Check if all dicts -> list with item_schema
        if all(isinstance(v, dict) for v in value):
            # Use first item as representative
            nested = []
            if value:
                for k, v in value[0].items():
                    nested.append(_infer_field(k, v))
            return InferredField(
                name=name,
                type="list",
                example_value=value,
                nested_fields=nested,
            )

        return InferredField(name=name, type="list", example_value=value)

    if isinstance(value, dict):
        nested = [_infer_field(k, v) for k, v in value.items()]
        return InferredField(
            name=name,
            type="object",
            example_value=value,
            nested_fields=nested,
        )

    return InferredField(name=name, type="any", example_value=value)


def _field_to_schema(f: InferredField) -> dict[str, Any]:
    """Convert an InferredField to a schema field dict."""
    result: dict[str, Any] = {"type": f.type, "required": f.required}

    if f.description:
        result["description"] = f.description

    # Float range auto-detection
    if f.type == "float" and isinstance(f.example_value, float):
        if 0.0 <= f.example_value <= 1.0:
            result["range"] = [0.0, 1.0]

    # List with item_schema (nested dicts)
    if f.type == "list" and f.nested_fields:
        item_schema: dict[str, Any] = {}
        for nf in f.nested_fields:
            item_schema[nf.name] = _field_to_schema(nf)
        result["item_schema"] = item_schema

    # Object with nested fields
    if f.type == "object" and f.nested_fields:
        nested: dict[str, Any] = {}
        for nf in f.nested_fields:
            nested[nf.name] = _field_to_schema(nf)
        result["nested_fields"] = nested

    return result


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------


def infer_schema_from_example(
    example: dict[str, Any],
    agent: str,
    schema_name: str,
    extends: str | None = "default",
) -> dict[str, Any]:
    """Create a schema dict from an example output dict.

    Parameters
    ----------
    example:
        A concrete example of agent output.
    agent:
        Agent name (e.g. ``"intent"``, ``"execution"``, ``"verify"``).
    schema_name:
        Name for the generated schema.
    extends:
        Base schema to inherit from.  Set to ``None`` to skip
        inheritance.

    Returns
    -------
    dict
        A complete schema dict ready for ``write_schema()``.
    """
    schema: dict[str, Any] = {
        "schema": {
            "name": schema_name,
            "version": "1.0",
            "agent": agent,
            "description": f"Auto-generated schema from example for {agent}",
        },
        "fields": {},
    }

    if extends is not None:
        schema["extends"] = extends

    for key, value in example.items():
        inferred = _infer_field(key, value)
        schema["fields"][key] = _field_to_schema(inferred)

    return schema


def write_schema(schema: dict[str, Any], path: Path | str) -> None:
    """Write a schema dict to a YAML file.

    Uses ``sort_keys=False`` to preserve field ordering for readability.
    """
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        yaml.dump(
            schema,
            fh,
            default_flow_style=False,
            sort_keys=False,
            allow_unicode=True,
        )

"""Tests for the schema system — loader, validator, and generator."""

from __future__ import annotations

import threading
from pathlib import Path

import pytest
import yaml

from agent.schemas import (
    clear_cache,
    infer_schema_from_example,
    list_schemas,
    load_schema,
    validate_output,
    write_schema,
)
from agent.schemas.loader import (
    SCHEMAS_DIR,
    _merge_schemas,
    _validate_type,
)


# ---------------------------------------------------------------------------
# Fixtures
# ---------------------------------------------------------------------------


@pytest.fixture(autouse=True)
def _clear_schema_cache():
    """Ensure each test starts with a clean cache."""
    clear_cache()
    yield
    clear_cache()


# ---------------------------------------------------------------------------
# Schema Loading
# ---------------------------------------------------------------------------


class TestLoadSchema:
    """Tests for load_schema resolution and caching."""

    def test_load_intent_default(self):
        schema = load_schema("intent")
        assert schema["schema"]["name"] == "IntentSpecification"
        assert schema["schema"]["agent"] == "intent"
        assert "fields" in schema
        assert "model_id" in schema["fields"]

    def test_load_execution_default(self):
        schema = load_schema("execution")
        assert schema["schema"]["name"] == "ExecutionResult"
        assert "status" in schema["fields"]

    def test_load_verify_default(self):
        schema = load_schema("verify")
        assert schema["schema"]["name"] == "VerificationResult"
        assert "overall_score" in schema["fields"]
        assert "decision" in schema["fields"]

    def test_schema_is_deep_copy(self):
        s1 = load_schema("intent")
        s2 = load_schema("intent")
        assert s1 == s2
        s1["fields"]["model_id"]["type"] = "MUTATED"
        s3 = load_schema("intent")
        assert s3["fields"]["model_id"]["type"] == "string"

    def test_missing_agent_raises(self):
        with pytest.raises(FileNotFoundError):
            load_schema("nonexistent_agent_xyz")

    def test_explicit_default_name(self):
        schema = load_schema("intent", "default")
        assert schema["schema"]["name"] == "IntentSpecification"


class TestSchemaCache:
    """Tests for thread-safe caching."""

    def test_cache_hit(self):
        s1 = load_schema("intent")
        s2 = load_schema("intent")
        assert s1 == s2

    def test_clear_cache(self):
        load_schema("intent")
        clear_cache()
        # Should still work — reloads from disk
        s = load_schema("intent")
        assert s["schema"]["name"] == "IntentSpecification"

    def test_thread_safety(self):
        """Multiple threads loading schemas concurrently."""
        results: list[dict] = []
        errors: list[Exception] = []

        def load_in_thread():
            try:
                s = load_schema("intent")
                results.append(s)
            except Exception as exc:
                errors.append(exc)

        threads = [threading.Thread(target=load_in_thread) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert not errors
        assert len(results) == 10
        # All results should be equivalent
        for r in results:
            assert r["schema"]["name"] == "IntentSpecification"


class TestSchemaResolution:
    """Tests for custom -> standard -> default fallback."""

    def test_custom_override(self, tmp_path):
        """Custom schema takes priority over default."""
        import agent.schemas.loader as loader_mod

        original_dir = loader_mod.SCHEMAS_DIR
        try:
            # Set up temp schema directory
            loader_mod.SCHEMAS_DIR = tmp_path
            agent_dir = tmp_path / "test_agent"
            agent_dir.mkdir()
            (agent_dir / "custom").mkdir()

            # Write default
            default = {
                "schema": {"name": "Default", "version": "1.0", "agent": "test_agent"},
                "fields": {"a": {"type": "string", "required": True}},
            }
            with open(agent_dir / "default.yaml", "w", encoding="utf-8") as f:
                yaml.dump(default, f)

            # Write custom
            custom = {
                "schema": {"name": "Custom", "version": "1.0", "agent": "test_agent"},
                "fields": {
                    "a": {"type": "string", "required": True},
                    "b": {"type": "integer", "required": False},
                },
            }
            with open(
                agent_dir / "custom" / "myschema.yaml", "w", encoding="utf-8"
            ) as f:
                yaml.dump(custom, f)

            clear_cache()
            schema = load_schema("test_agent", "myschema")
            assert schema["schema"]["name"] == "Custom"
            assert "b" in schema["fields"]
        finally:
            loader_mod.SCHEMAS_DIR = original_dir

    def test_fallback_to_default(self, tmp_path):
        """Unknown schema_name falls back to default.yaml."""
        import agent.schemas.loader as loader_mod

        original_dir = loader_mod.SCHEMAS_DIR
        try:
            loader_mod.SCHEMAS_DIR = tmp_path
            agent_dir = tmp_path / "test_agent"
            agent_dir.mkdir()

            default = {
                "schema": {"name": "Fallback", "version": "1.0", "agent": "test_agent"},
                "fields": {"x": {"type": "string", "required": True}},
            }
            with open(agent_dir / "default.yaml", "w", encoding="utf-8") as f:
                yaml.dump(default, f)

            clear_cache()
            schema = load_schema("test_agent", "nonexistent")
            assert schema["schema"]["name"] == "Fallback"
        finally:
            loader_mod.SCHEMAS_DIR = original_dir


class TestSchemaInheritance:
    """Tests for extends-based schema merging."""

    def test_merge_adds_fields(self):
        base = {
            "schema": {"name": "Base", "version": "1.0"},
            "fields": {"a": {"type": "string", "required": True}},
        }
        ext = {
            "fields": {"b": {"type": "integer", "required": False}},
        }
        merged = _merge_schemas(base, ext)
        assert "a" in merged["fields"]
        assert "b" in merged["fields"]

    def test_merge_extension_wins_conflict(self):
        base = {
            "schema": {"name": "Base", "version": "1.0"},
            "fields": {"a": {"type": "string", "required": True}},
        }
        ext = {
            "schema": {"name": "Extended"},
            "fields": {"a": {"type": "integer", "required": False}},
        }
        merged = _merge_schemas(base, ext)
        assert merged["fields"]["a"]["type"] == "integer"
        assert merged["schema"]["name"] == "Extended"
        # Version preserved from base
        assert merged["schema"]["version"] == "1.0"

    def test_extends_field_in_yaml(self, tmp_path):
        """Schema with extends key loads and merges the base."""
        import agent.schemas.loader as loader_mod

        original_dir = loader_mod.SCHEMAS_DIR
        try:
            loader_mod.SCHEMAS_DIR = tmp_path
            agent_dir = tmp_path / "test_agent"
            agent_dir.mkdir()

            base = {
                "schema": {"name": "Base", "version": "1.0", "agent": "test_agent"},
                "fields": {
                    "a": {"type": "string", "required": True},
                    "b": {"type": "float", "required": True},
                },
            }
            with open(agent_dir / "default.yaml", "w", encoding="utf-8") as f:
                yaml.dump(base, f)

            ext = {
                "extends": "default",
                "schema": {"name": "Extended"},
                "fields": {
                    "c": {"type": "boolean", "required": False},
                },
            }
            with open(agent_dir / "extended.yaml", "w", encoding="utf-8") as f:
                yaml.dump(ext, f)

            clear_cache()
            schema = load_schema("test_agent", "extended")
            assert "a" in schema["fields"]
            assert "b" in schema["fields"]
            assert "c" in schema["fields"]
            assert schema["schema"]["name"] == "Extended"
        finally:
            loader_mod.SCHEMAS_DIR = original_dir

    def test_merge_preserves_base_immutability(self):
        base = {
            "schema": {"name": "Base"},
            "fields": {"a": {"type": "string"}},
        }
        ext = {"fields": {"a": {"type": "integer"}}}
        _merge_schemas(base, ext)
        # Base should be unchanged
        assert base["fields"]["a"]["type"] == "string"


# ---------------------------------------------------------------------------
# Output Validation
# ---------------------------------------------------------------------------


class TestValidateOutput:
    """Tests for validate_output against schemas."""

    def test_valid_intent_output(self):
        output = {
            "model_id": "sdxl-base",
            "parameter_mutations": [
                {
                    "target": "sampler.steps",
                    "action": "set",
                    "value": 25,
                    "reason": "Better quality",
                }
            ],
            "prompt_mutations": [
                {
                    "target": "positive_prompt",
                    "action": "append",
                    "value": "cinematic lighting",
                    "reason": "User asked for dreamier",
                }
            ],
            "confidence": 0.85,
        }
        errors = validate_output(output, "intent")
        assert errors == []

    def test_missing_required_field(self):
        output = {
            "parameter_mutations": [],
            "prompt_mutations": [],
            "confidence": 0.5,
        }
        errors = validate_output(output, "intent")
        assert any("model_id" in e for e in errors)

    def test_type_mismatch_string(self):
        output = {
            "model_id": 123,  # should be string
            "parameter_mutations": [],
            "prompt_mutations": [],
            "confidence": 0.5,
        }
        errors = validate_output(output, "intent")
        assert any("model_id" in e and "string" in e for e in errors)

    def test_type_mismatch_float(self):
        output = {
